window.RP_SESSION={"id":"S-37be20581475","messages":[{"id":"RP-0262985","time":"2026-09-05T16:27:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"땅, 땅, 땅, 땅, 땅. \n\n망치질 소리가 느긋한 오후에 울려 퍼집니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262986","time":"2026-09-05T16:29:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"길드 대문에서부터 이어진 울타리가 세워지다 말고 끊긴 지점. 션은 길드 뒷편 숲과 가까운 그곳에서 망치질을 하고 있었습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262987","time":"2026-09-05T16:30:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"자기 키보다 약간 긴 나무에 홈을 세 개씩 파낸 울타리 세로축을 번쩍 들어 땅에 꽂습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262988","time":"2026-09-05T16:30:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-3bbc4a823df9"]},{"id":"RP-0262989","time":"2026-09-05T16:30:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 힘 판정 :\n[6] + [4] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0262990","time":"2026-09-05T16:33:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"망치질 서너 번만에 깊숙하게 박히는 세로축.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262991","time":"2026-09-05T16:35:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이어서 가로축을 들어올린 션은, 양 옆 1.5미터 정도의 간격으로 세워진 세로축에 파인 홈 안에 끼워넣습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262992","time":"2026-09-05T16:43:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그런 뒤 농사에 쓰는 석회와 자갈 같은 잡석들을 섞은 포대를 끌러 박아넣은 울타리 주위에 골고루 뿌립니다. \n\n이어서 물까지 적절히 부어주면 펜스가 단단하게 굳을 것입니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262993","time":"2026-09-05T16:50:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"곧이어 또다시 1.5미터 정도 간격을 띄우고 세로축을 박습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262994","time":"2026-09-05T16:50:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-3bbc4a823df9"]},{"id":"RP-0262995","time":"2026-09-05T16:50:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 힘 판정 :\n[7] + [4] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0262996","time":"2026-09-05T16:57:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어젯밤 시장에서 돌아온 델타인을 시켜 땅을 파고 다져놓은 곳에서… 땅, 땅, 땅, 땅!","characters":["P-3bbc4a823df9"]},{"id":"RP-0262997","time":"2026-09-05T17:01:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이러면 어쩌다 숲으로 걸어 들어가서 홀로 길을 잃는 인원들이 줄어들 겁니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0262998","time":"2026-09-05T17:01:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"…조금은?","characters":["P-3bbc4a823df9"]},{"id":"RP-0262999","time":"2026-09-05T17:05:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"울타리 문은 마땅히 없으니 한 지점을 비워 놓았겠네요.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263000","time":"2026-09-05T17:07:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"흠…. \n\n브랜이 문짝도 만들 수 있을까요?\n\n션은 금연 파이프를 입에 물고서 생각에 잠겼습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263001","time":"2026-09-05T17:11:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아침 기도 시간에 시작한 작업은 저녁 먹을 때가 다가오고 나서야 끝났습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263002","time":"2026-09-05T17:15:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"망치를 아무렇게나 던져두고, 두레박으로 우물물을 끌어 올리며 상의를 벗어제낍니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263003","time":"2026-09-05T17:15:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"떡 벌어진 어깨, 근육이 달라붙은 기다란 팔.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263004","time":"2026-09-05T17:16:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"원래 이런 건 토르번 시키면 편했는데, 공대장이 되어서 조금은 아쉽게 됐네요.","characters":["P-3bbc4a823df9"]},{"id":"RP-0263005","time":"2026-09-05T17:16:00+09:00","room":"RP","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-0263006","time":"2026-09-05T17:16:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
